-- Migration: Year 2 - Reproductive Pathology MCQs Part 1 (1-80)
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Reproductive Pathology', 'reproductive-pathology', 3, 2, 60)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- MALE: CONGENITAL & INFLAMMATORY (1-10)
    (v_topic_id, '1. Hypospadias is characterized by the abnormal opening of the urethra on which surface of the penis?', '["Ventral surface", "Dorsal surface", "Lateral surface", "Base of the scrotum"]', 0, 'Hypospadias involves an opening on the ventral (inferior) surface of the penis due to failure of the urethral folds to close.'),
    (v_topic_id, '2. Epispadias is characterized by an abnormal opening on the dorsal surface of the penis. It is frequently associated with which other developmental anomaly?', '["Cryptorchidism", "Exstrophy of the bladder", "Horseshoe kidney", "Prune belly syndrome"]', 1, 'Epispadias is due to abnormal positioning of the genital tubercle and is strongly associated with bladder exstrophy.'),
    (v_topic_id, '3. A 2-year-old male is evaluated for an empty left hemiscrotum. What is the most significant long-term risk if this condition (Cryptorchidism) is not surgically corrected?', '["Prostate cancer", "Infertility and increased risk of testicular cancer", "Recurrent UTIs", "Erectile dysfunction"]', 1, 'Cryptorchidism causes testicular atrophy (infertility) and a significantly increased risk of germ cell tumors (especially seminoma) even if surgically corrected (orchiopexy).'),
    (v_topic_id, '4. A 20-year-old male presents with acute, severe scrotal pain and swelling. The cremasteric reflex is absent. What is the underlying pathophysiology?', '["Viral infection of the testes", "Twisting of the spermatic cord cutting off venous drainage", "Autoimmune destruction of Leydig cells", "Bacterial infection ascending from the urethra"]', 1, 'Testicular torsion involves twisting of the spermatic cord, blocking thin-walled veins. Arterial blood continues to enter, leading to severe hemorrhagic infarction.'),
    (v_topic_id, '5. A 25-year-old male presents with a painless, fluid-filled mass in his scrotum that transilluminates when a light is shone through it. Diagnosis?', '["Varicocele", "Spermatocele", "Hydrocele", "Testicular cancer"]', 2, 'A hydrocele is a fluid collection within the tunica vaginalis. It transilluminates, unlike solid testicular tumors.'),
    (v_topic_id, '6. What causes a communicating hydrocele in an infant?', '["Incomplete obliteration of the processus vaginalis", "Trauma", "Epididymitis", "Lymphatic blockage"]', 0, 'Failure of the processus vaginalis to close allows peritoneal fluid to enter the tunica vaginalis sac.'),
    (v_topic_id, '7. A 30-year-old male complains of a "bag of worms" sensation in his left scrotum. This condition is caused by dilation of which structure?', '["Epididymis", "Pampiniform plexus of veins", "Vas deferens", "Seminiferous tubules"]', 1, 'A varicocele is a dilation of the pampiniform plexus. It is almost always on the left side due to the left gonadal vein draining into the left renal vein at a 90-degree angle.'),
    (v_topic_id, '8. A right-sided varicocele in an older male should raise immediate suspicion for which underlying condition?', '["Renal cell carcinoma", "Prostate cancer", "Testicular torsion", "Retroperitoneal lymphadenopathy or inferior vena cava block"]', 3, 'Because the right gonadal vein drains directly into the IVC, a right-sided varicocele suggests a mass blocking the IVC or right gonadal vein.'),
    (v_topic_id, '9. Orchitis in young, sexually active males (under 35) is most commonly caused by?', '["Escherichia coli and Pseudomonas", "Chlamydia trachomatis and Neisseria gonorrhoeae", "Mumps virus", "Mycobacterium tuberculosis"]', 1, 'C. trachomatis (D-K) and N. gonorrhoeae are the most common causes of epididymitis and orchitis in young adults.'),
    (v_topic_id, '10. Orchitis in older males (over 35) is most commonly caused by?', '["Chlamydia trachomatis", "Neisseria gonorrhoeae", "Escherichia coli and Pseudomonas", "Treponema pallidum"]', 2, 'In older men, it is typically associated with urinary tract infections or BPH caused by typical urinary pathogens like E. coli.'),

    -- MALE: TESTICULAR TUMORS (11-25)
    (v_topic_id, '11. Testicular tumors are generally divided into two main categories: Germ Cell Tumors and Sex Cord-Stromal Tumors. Which category accounts for >95% of cases?', '["Sex Cord-Stromal Tumors", "Germ Cell Tumors", "Metastatic tumors", "Lymphomas"]', 1, 'Germ cell tumors (GCTs) are the most common testicular tumor and typically occur in young men (15-35 years old).'),
    (v_topic_id, '12. Why should a firm, painless testicular mass NEVER be biopsied transscrotally?', '["It causes severe pain", "Risk of seeding the scrotum with tumor cells", "Biopsies are notoriously inaccurate", "It causes immediate hemorrhage"]', 1, 'Biopsy risks seeding the cancer into the scrotal sac and altering lymphatic drainage. Diagnosis is made via radical orchiectomy.'),
    (v_topic_id, '13. What is the most common testicular germ cell tumor in adult males?', '["Yolk sac tumor", "Choriocarcinoma", "Seminoma", "Teratoma"]', 2, 'Seminoma is the most common GCT, presenting as a painless mass. It responds remarkably well to radiotherapy.'),
    (v_topic_id, '14. A 30-year-old male has a testicular mass. Histology shows large cells with clear cytoplasm and central nuclei resembling "fried eggs," arranged in lobules with a lymphocytic infiltrate. Diagnosis?', '["Embryonal carcinoma", "Seminoma", "Leydig cell tumor", "Choriocarcinoma"]', 1, 'The "fried egg" appearance with a prominent lymphocytic infiltrate and fibrous septae is pathognomonic for Seminoma.'),
    (v_topic_id, '15. Which tumor marker is frequently elevated in Seminoma?', '["Alpha-fetoprotein (AFP)", "Prostate-specific antigen (PSA)", "Human chorionic gonadotropin (hCG)", "Placental alkaline phosphatase (PLAP)"]', 3, 'Seminomas often have elevated PLAP. They may also have slightly elevated hCG, but AFP is NEVER elevated in pure seminoma.'),
    (v_topic_id, '16. A 25-year-old male presents with a painful, hemorrhagic testicular mass. Histology shows primitive, pleomorphic cells in glandular patterns. AFP and hCG are elevated. Diagnosis?', '["Seminoma", "Embryonal carcinoma", "Yolk sac tumor", "Teratoma"]', 1, 'Embryonal carcinoma is a malignant, aggressive GCT consisting of primitive cells. It is often mixed with other types (hence mixed markers) and is painful and hemorrhagic.'),
    (v_topic_id, '17. What is the most common testicular tumor in children under 3 years old?', '["Seminoma", "Teratoma", "Yolk sac (Endodermal sinus) tumor", "Choriocarcinoma"]', 2, 'Yolk sac tumor is the most common testicular tumor in young children and has an excellent prognosis.'),
    (v_topic_id, '18. Which histological finding is pathognomonic for a Yolk Sac Tumor?', '["Fried egg cells", "Reinke crystals", "Schiller-Duval bodies", "Call-Exner bodies"]', 2, 'Schiller-Duval bodies resemble primitive glomeruli (a blood vessel surrounded by germ cells inside a cystic space).'),
    (v_topic_id, '19. Which tumor marker is characteristically elevated in Yolk Sac Tumors?', '["hCG", "CA-125", "Alpha-fetoprotein (AFP)", "CEA"]', 2, 'AFP is highly elevated in yolk sac tumors, reflecting its endodermal (yolk sac/fetal liver) origin.'),
    (v_topic_id, '20. A 28-year-old male presents with massive hemoptysis and gynecomastia. A tiny, highly necrotic mass is found in his right testis. Which tumor is most likely?', '["Choriocarcinoma", "Seminoma", "Leydig cell tumor", "Teratoma"]', 0, 'Choriocarcinoma is a highly malignant tumor of syncytiotrophoblasts and cytotrophoblasts. It spreads rapidly via the blood (often to lungs).'),
    (v_topic_id, '21. Why does Choriocarcinoma cause gynecomastia and hyperthyroidism?', '["It secretes estrogen", "It secretes massively high levels of hCG", "It secretes prolactin", "It destroys the testicle"]', 1, 'hCG has an alpha subunit identical to LH, FSH, and TSH. High hCG mimics LH (causing gynecomastia) and TSH (causing hyperthyroidism).'),
    (v_topic_id, '22. In contrast to females, a mature Teratoma in a post-pubertal male is considered:', '["Benign", "Malignant", "Premalignant", "Self-resolving"]', 1, 'While mature teratomas are benign in females, they are considered malignant in adult males.'),
    (v_topic_id, '23. A 6-year-old boy presents with precocious puberty. A testicular ultrasound reveals a solid mass. Histology shows eosinophilic cells with rod-shaped Reinke crystals. Diagnosis?', '["Sertoli cell tumor", "Leydig cell tumor", "Seminoma", "Teratoma"]', 1, 'Leydig cell tumors produce androgens (causing precocious puberty in kids) or estrogens (causing gynecomastia in adults). Reinke crystals are pathognomonic.'),
    (v_topic_id, '24. Sertoli cell tumors are typically benign. They are characterized histologically by the formation of?', '["Reinke crystals", "Schiller-Duval bodies", "Tubules", "Fried egg cells"]', 2, 'Sertoli cells normally line the seminiferous tubules, so their tumors typically form rudimentary tubules.'),
    (v_topic_id, '25. What is the most common cause of a testicular mass in an elderly male (>60 years old)?', '["Seminoma", "Testicular Lymphoma", "Leydig cell tumor", "Teratoma"]', 1, 'Primary testicular lymphoma (usually Diffuse Large B-Cell Lymphoma) is the most common cause of a testicular mass in men >60 and is often bilateral.'),

    -- MALE: PROSTATE & PENIS (26-40)
    (v_topic_id, '26. Benign Prostatic Hyperplasia (BPH) predominantly occurs in which zone of the prostate?', '["Peripheral zone", "Transition zone", "Central zone", "Anterior fibromuscular stroma"]', 1, 'BPH occurs in the transition (periurethral) zone, directly compressing the urethra and causing urinary symptoms (hesitancy, dribbling, nocturia).'),
    (v_topic_id, '27. Which hormone is the primary driver of prostate gland hyperplasia in BPH?', '["Testosterone", "Dihydrotestosterone (DHT)", "Estrogen", "Progesterone"]', 1, 'Testosterone is converted to DHT by 5-alpha-reductase in the prostate stromal cells. DHT binds receptors and drives hyperplastic growth.'),
    (v_topic_id, '28. A patient with BPH is prescribed Finasteride. What is the mechanism of action?', '["Alpha-1 receptor blocker", "5-alpha-reductase inhibitor", "Androgen receptor antagonist", "Phosphodiesterase-5 inhibitor"]', 1, 'Finasteride blocks the conversion of testosterone to DHT, slowly shrinking the prostate gland over months.'),
    (v_topic_id, '29. Prostate Adenocarcinoma predominantly arises in which zone of the prostate?', '["Transition zone", "Central zone", "Peripheral zone", "Fibromuscular zone"]', 2, 'Prostate cancer typically arises in the peripheral zone (usually posterior). This is why it can be palpated on a Digital Rectal Exam (DRE) but rarely causes early urinary symptoms.'),
    (v_topic_id, '30. Which scoring system is used to grade Prostate Adenocarcinoma based on its architectural pattern?', '["Gleason grading system", "Fuhrman grade", "Nottingham score", "Ann Arbor staging"]', 0, 'The Gleason score is based entirely on the glandular architecture (not nuclear atypia). Two different regions are graded 1-5 and added together (e.g., 4+3=7).'),
    (v_topic_id, '31. Where does Prostate Adenocarcinoma most characteristically metastasize?', '["Lungs", "Liver", "Bone (causing osteoblastic lesions)", "Brain"]', 2, 'Prostate cancer spreads via the Batson venous plexus to the lumbar spine and pelvis, causing dense, bone-forming (osteoblastic) metastases.'),
    (v_topic_id, '32. A patient with osteoblastic metastases from prostate cancer will likely have an elevation of which serum marker (besides PSA)?', '["Acid phosphatase", "Alkaline phosphatase (ALP)", "Alpha-fetoprotein", "LDH"]', 1, 'ALP is elevated when there is active bone formation (osteoblastic activity).'),
    (v_topic_id, '33. Squamous Cell Carcinoma of the penis is rare in the US. What is the most significant protective factor?', '["Frequent bathing", "Neonatal circumcision", "Use of condoms", "High-fiber diet"]', 1, 'Neonatal circumcision removes the foreskin, preventing the accumulation of smegma and reducing the risk of HPV infection, almost eliminating the risk of penile SCC.'),
    (v_topic_id, '34. Which high-risk viral strains are most strongly associated with Penile Squamous Cell Carcinoma?', '["HSV-2", "HPV 6 and 11", "HPV 16 and 18", "EBV"]', 2, 'High-risk HPV types 16 and 18 integrate their DNA and express E6/E7, leading to squamous dysplasia and carcinoma.'),
    (v_topic_id, '35. Bowen disease of the penis presents as an opaque, leukoplakic plaque on the penile shaft. What does it represent pathologically?', '["Benign hyperkeratosis", "Squamous Cell Carcinoma in situ", "Invasive Squamous Cell Carcinoma", "Viral wart (Condyloma acuminatum)"]', 1, 'Bowen disease is SCC in situ. It has a 10% risk of progressing to invasive carcinoma.'),
    (v_topic_id, '36. Erythroplasia of Queyrat is similar to Bowen disease but presents as?', '["A red, velvety plaque on the glans penis", "Multiple reddish-brown papules", "A deep, painful ulcer", "A cauliflower-like mass"]', 0, 'It is SCC in situ specifically located on the glans (head) of the penis, presenting as a red patch.'),
    (v_topic_id, '37. Bowenoid papulosis presents as multiple reddish-brown papules in a younger patient. What is its typical clinical course?', '["Rapid progression to invasive cancer", "Spontaneous regression", "Metastasis to inguinal lymph nodes", "Development of severe pain"]', 1, 'Unlike Bowen disease, Bowenoid papulosis (also SCC in situ) usually does not progress to invasive cancer and often regresses spontaneously.'),
    (v_topic_id, '38. Which congenital anomaly features the urethral opening on the dorsal aspect of the penis?', '["Hypospadias", "Epispadias", "Phimosis", "Paraphimosis"]', 1, 'Epispadias ("epi" = upon/dorsal).'),
    (v_topic_id, '39. Condyloma acuminatum is a benign warty growth on the genitals. Which HPV strains cause it?', '["HPV 16 and 18", "HPV 31 and 33", "HPV 6 and 11", "HPV 1 and 2"]', 2, 'HPV 6 and 11 cause benign genital warts. They feature characteristic "koilocytes" (cells with wrinkled "raisin" nuclei and perinuclear halos).'),
    (v_topic_id, '40. What is the defining microscopic feature of HPV infection in squamous cells?', '["Reinke crystals", "Koilocytosis", "Negri bodies", "Cowdry A inclusions"]', 1, 'Koilocytes are the histological hallmark of HPV infection.'),

    -- FEMALE: VULVA & VAGINA (41-60)
    (v_topic_id, '41. A 25-year-old female presents with a painful, cystic swelling in the lower vestibule, adjacent to the vaginal canal. Diagnosis?', '["Gartner duct cyst", "Bartholin cyst/abscess", "Nabothian cyst", "Skene gland cyst"]', 1, 'Bartholin glands produce mucus for lubrication. Obstruction of the duct leads to a cyst, which can easily become infected and form a painful abscess.'),
    (v_topic_id, '42. A postmenopausal woman complains of severe vulvar itching. Exam reveals thinning of the epidermis ("parchment-like" skin) and dermal fibrosis. Diagnosis?', '["Lichen Simplex Chronicus", "Lichen Sclerosus", "Vulvar Carcinoma", "Psoriasis"]', 1, 'Lichen Sclerosus causes thin, white, parchment-like skin. It carries a slight increased risk of progressing to squamous cell carcinoma.'),
    (v_topic_id, '43. A woman presents with thick, leathery vulvar skin due to chronic rubbing and scratching. Diagnosis?', '["Lichen Sclerosus", "Lichen Simplex Chronicus", "Condyloma acuminatum", "Vulvar intraepithelial neoplasia"]', 1, 'Lichen Simplex Chronicus involves squamous cell hyperplasia (thickening) due to chronic irritation. It is benign with no cancer risk.'),
    (v_topic_id, '44. High-risk HPV (16, 18) is associated with which type of Vulvar Carcinoma?', '["Basaloid and Warty squamous cell carcinoma", "Keratinizing squamous cell carcinoma", "Adenocarcinoma", "Melanoma"]', 0, 'HPV-related vulvar SCC usually occurs in reproductive-age women and is preceded by Vulvar Intraepithelial Neoplasia (VIN).'),
    (v_topic_id, '45. Non-HPV related Vulvar Carcinoma typically arises from which preceding condition in older, postmenopausal women?', '["Lichen Simplex Chronicus", "Lichen Sclerosus", "Condyloma acuminatum", "Endometriosis"]', 1, 'Long-standing Lichen Sclerosus can progress to keratinizing squamous cell carcinoma in older women.'),
    (v_topic_id, '46. Extramammary Paget Disease of the vulva presents as an erythematous, pruritic, ulcerated skin lesion. It represents?', '["Malignant epithelial cells (carcinoma in situ) in the epidermis", "A deep fungal infection", "Invasive melanoma", "Squamous cell carcinoma"]', 0, 'Unlike Paget disease of the breast, vulvar Paget disease is usually NOT associated with an underlying invasive carcinoma. It represents intraepidermal adenocarcinoma.'),
    (v_topic_id, '47. How can you differentiate Extramammary Paget Disease from Vulvar Melanoma, as both can look similar?', '["Paget cells are PAS-positive, Melanoma is S100-positive", "Paget cells are S100-positive, Melanoma is PAS-positive", "Paget cells are Vimentin-positive", "Melanoma is Keratin-positive"]', 0, 'Paget cells are epithelial (mucin-producing), so they are PAS+, Keratin+, and S100-. Melanoma is neural crest-derived, so it is PAS-, Keratin-, and S100+.'),
    (v_topic_id, '48. The vagina is normally lined by non-keratinizing squamous epithelium. Vaginal Adenosis is the persistence of which type of tissue in the upper vagina?', '["Transitional epithelium", "Columnar epithelium (Mullerian tissue)", "Mesothelium", "Stratified cuboidal epithelium"]', 1, 'During development, squamous epithelium from the urogenital sinus grows up and replaces the Mullerian columnar epithelium. Failure of this replacement leaves patches of columnar epithelium (adenosis).'),
    (v_topic_id, '49. Vaginal Adenosis is strongly associated with maternal exposure to which drug during pregnancy?', '["Thalidomide", "Diethylstilbestrol (DES)", "Lithium", "Isotretinoin"]', 1, 'DES, a synthetic estrogen given to prevent miscarriages, caused vaginal adenosis in female offspring.'),
    (v_topic_id, '50. Daughters exposed to DES in utero are at a significantly increased risk of developing which rare vaginal cancer?', '["Squamous cell carcinoma", "Clear cell adenocarcinoma", "Embryonal rhabdomyosarcoma", "Melanoma"]', 1, 'The patches of vaginal adenosis (columnar cells) can undergo malignant transformation into clear cell adenocarcinoma.'),
    (v_topic_id, '51. A 3-year-old girl presents with bleeding and a grape-like mass protruding from the vagina. Diagnosis?', '["Clear cell adenocarcinoma", "Embryonal rhabdomyosarcoma (Sarcoma botryoides)", "Vaginal adenosis", "Bartholin cyst"]', 1, 'Sarcoma botryoides is a malignant skeletal muscle tumor that classicially forms a "bunch of grapes" mass in young girls.'),
    (v_topic_id, '52. What is the characteristic histological finding in Embryonal Rhabdomyosarcoma?', '["Koilocytes", "Rhabdomyoblasts showing cytoplasmic cross-striations", "Clear cells", "Fried egg cells"]', 1, 'The cells are immature muscle cells (rhabdomyoblasts). They stain positive for Desmin and Myogenin.'),
    (v_topic_id, '53. Vaginal Squamous Cell Carcinoma is usually secondary to HPV. Where does cancer in the LOWER 1/3 of the vagina spread to first?', '["Pelvic lymph nodes", "Inguinal lymph nodes", "Para-aortic lymph nodes", "Lungs"]', 1, 'The lower 1/3 of the vagina drains to the superficial inguinal nodes. The upper 2/3 drains to regional pelvic (iliac) nodes.'),
    (v_topic_id, '54. What is the embryological origin of the upper 2/3 of the vagina?', '["Urogenital sinus", "Wolffian (mesonephric) ducts", "Mullerian (paramesonephric) ducts", "Genital tubercle"]', 2, 'The upper vagina, cervix, uterus, and fallopian tubes derive from the Mullerian ducts. The lower 1/3 of the vagina derives from the urogenital sinus.'),
    (v_topic_id, '55. A Gartner duct cyst is found on the lateral wall of the vagina. It is a remnant of the?', '["Mullerian duct", "Wolffian (mesonephric) duct", "Urogenital sinus", "Urachus"]', 1, 'The Wolffian duct normally degenerates in females, but remnants can persist as Gartner duct cysts along the lateral vaginal wall.'),
    (v_topic_id, '56. In the transformation zone of the cervix, what cellular change normally occurs?', '["Columnar epithelium undergoes squamous metaplasia", "Squamous epithelium undergoes columnar metaplasia", "Hyperplasia of glands", "Dysplasia of squamous cells"]', 0, 'The acidic environment of the vagina causes the exposed columnar cells of the endocervix to undergo squamous metaplasia. This active transition zone is highly susceptible to HPV infection.'),
    (v_topic_id, '57. Which two HPV proteins are responsible for driving cervical carcinogenesis?', '["E1 and E2", "E4 and E5", "E6 and E7", "L1 and L2"]', 2, 'E6 and E7 are the primary oncogenes.'),
    (v_topic_id, '58. How does the HPV E6 protein promote cancer?', '["It degrades the p53 tumor suppressor gene", "It degrades the Rb tumor suppressor gene", "It acts as a growth factor", "It causes massive DNA breaks"]', 0, 'E6 marks p53 for destruction, preventing the cell from undergoing apoptosis if DNA damage occurs.'),
    (v_topic_id, '59. How does the HPV E7 protein promote cancer?', '["It degrades p53", "It binds and inactivates the Retinoblastoma (Rb) protein", "It stimulates angiogenesis", "It inhibits telomerase"]', 1, 'E7 binds Rb, releasing the E2F transcription factor, which pushes the cell relentlessly through the G1-S cell cycle checkpoint.'),
    (v_topic_id, '60. Cervical Intraepithelial Neoplasia (CIN) is graded I, II, and III. What defines CIN I?', '["Dysplasia involving the entire thickness of the epithelium", "Dysplasia involving the lower 1/3 of the epithelium", "Invasion through the basement membrane", "Normal epithelium with koilocytes"]', 1, 'CIN I (low-grade dysplasia) involves the lower third. CIN II involves the lower 2/3. CIN III involves almost the entire thickness. Carcinoma in situ (CIS) is full thickness.'),

    -- FEMALE: CERVIX (61-80)
    (v_topic_id, '61. True or False: CIN I often reverses completely on its own without treatment.', '["True", "False", "Only with antivirals", "Only after menopause"]', 0, 'Up to 60-66% of CIN I lesions regress spontaneously. Even CIN II can regress, though less frequently.'),
    (v_topic_id, '62. What distinguishes Cervical Carcinoma in situ (CIS) from Invasive Squamous Cell Carcinoma?', '["Presence of koilocytes", "Invasion through the basement membrane into the stroma", "Involvement of the upper 1/3 of epithelium", "Presence of HPV 16"]', 1, 'Invasive carcinoma breaks through the epithelial basement membrane into the underlying cervical stroma.'),
    (v_topic_id, '63. A Pap smear (Papanicolaou test) is used to screen for?', '["Ovarian cancer", "Endometrial cancer", "Cervical dysplasia and carcinoma", "Vaginal melanoma"]', 2, 'It scrapes cells from the transformation zone to detect dysplastic changes (CIN) before they become invasive.'),
    (v_topic_id, '64. What is the most common symptom of invasive cervical carcinoma?', '["Pelvic pain", "Postcoital bleeding", "Amenorrhea", "Fever"]', 1, 'The friable tumor on the cervix often bleeds after sexual intercourse (postcoital bleeding).'),
    (v_topic_id, '65. How does advanced cervical carcinoma most commonly cause death?', '["Brain metastases", "Liver failure", "Direct invasion of the anterior wall into the bladder, blocking the ureters and causing renal failure", "Massive hemorrhage"]', 2, 'Cervical cancer typically spreads via direct local extension rather than distant blood metastases. It invades the bladder/ureters, causing bilateral hydronephrosis and postrenal failure.'),
    (v_topic_id, '66. The current HPV vaccine (Gardasil 9) protects against which virus types?', '["Only HPV 16 and 18", "Only HPV 6 and 11", "HPV 6, 11, 16, 18, and 5 other high-risk strains", "All HPV strains"]', 2, 'It protects against the major wart-causing strains (6, 11) and major cancer-causing strains (16, 18, 31, 33, etc.).'),
    (v_topic_id, '67. What is the primary limitation of the Pap smear?', '["It is too expensive", "It cannot detect adenocarcinoma of the cervix very well", "It is highly invasive", "It causes bleeding"]', 1, 'While excellent at catching squamous dysplasia, it is less effective at detecting adenocarcinoma, which arises higher up in the endocervical glands.'),
    (v_topic_id, '68. Endocervical polyps are benign exophytic growths. How do they commonly present?', '["Postcoital bleeding or spotting", "Severe pelvic pain", "Infertility", "Foul-smelling discharge"]', 0, 'Like cervical cancer, they can present with irregular or postcoital spotting, but they are completely benign and not linked to HPV.'),
    (v_topic_id, '69. What type of epithelium lines the ECTOcervix (outer cervix facing the vagina)?', '["Simple columnar", "Non-keratinizing stratified squamous", "Transitional", "Pseudostratified ciliated columnar"]', 1, 'It is continuous with the vaginal lining.'),
    (v_topic_id, '70. What type of epithelium lines the ENDOcervix (the canal)?', '["Non-keratinizing stratified squamous", "Mucus-secreting simple columnar", "Transitional", "Keratinizing squamous"]', 1, 'The endocervical canal produces mucus to facilitate or block sperm transport depending on the menstrual cycle phase.'),
    (v_topic_id, '71. A 35-year-old woman has a Pap smear showing High-Grade Squamous Intraepithelial Lesion (HSIL). What is the next best step in management?', '["Reassurance and repeat Pap in 3 years", "Immediate hysterectomy", "Colposcopy with directed biopsy", "Prescribe antibiotics"]', 2, 'Abnormal Pap smears (a screening test) must be followed up with a Colposcopy (diagnostic test) to visualize the cervix with acetic acid and biopsy the abnormal areas.'),
    (v_topic_id, '72. During colposcopy, acetic acid is applied to the cervix. What does dysplastic (abnormal) tissue look like?', '["It turns dark brown", "It turns bright red", "It turns white (acetowhite changes)", "It disappears"]', 2, 'Acetic acid causes areas of high nuclear density (dysplasia) to reflect light and appear stark white.'),
    (v_topic_id, '73. Which lymph nodes are typically the first to be involved in the spread of cervical carcinoma?', '["Inguinal nodes", "Pelvic (Paracervical, Iliac) nodes", "Para-aortic nodes", "Supraclavicular nodes"]', 1, 'Cervical lymphatics drain directly to the regional pelvic nodes (internal, external iliac, and obturator).'),
    (v_topic_id, '74. True or False: Routine Pap smears are recommended for all women starting at age 21, regardless of sexual activity onset.', '["True", "False", "Only if symptomatic", "Start at age 18"]', 0, 'Guidelines generally recommend starting Pap screening at age 21.'),
    (v_topic_id, '75. What is the difference between CIN III and Carcinoma In Situ (CIS)?', '["CIN III only involves 2/3 of the epithelium", "CIS involves the basement membrane", "They are essentially synonymous clinically and represent full-thickness dysplasia", "CIN III is benign, CIS is malignant"]', 2, 'Both terms describe severe dysplasia encompassing virtually the entire thickness of the epithelium without breaching the basement membrane.'),
    (v_topic_id, '76. A 40-year-old woman is diagnosed with invasive cervical carcinoma. What is the most significant risk factor in her history?', '["Early age of first sexual intercourse and multiple partners", "Nulliparity", "Obesity", "Family history of cervical cancer"]', 0, 'These factors dramatically increase the risk of exposure to high-risk HPV strains, which is the necessary cause of almost all cervical cancers.'),
    (v_topic_id, '77. Does smoking increase the risk of cervical cancer?', '["No, it only affects the lungs", "Yes, it acts as a co-factor in HPV-mediated carcinogenesis", "Only if the patient does not have HPV", "Yes, but it prevents vulvar cancer"]', 1, 'Smoking is a proven co-factor that increases the risk of cervical dysplasia progressing to cancer in HPV-positive women.'),
    (v_topic_id, '78. A patient undergoes a cone biopsy for CIN III. What is a potential future complication of this procedure?', '["Uterine rupture", "Cervical incompetence leading to premature delivery", "Ovarian failure", "Vaginal agenesis"]', 1, 'Removing a cone-shaped wedge of the cervix can weaken it, increasing the risk of the cervix opening too early during a future pregnancy.'),
    (v_topic_id, '79. Which HPV oncoprotein is responsible for maintaining the viral genome as an episome?', '["E6", "E7", "E2", "L1"]', 2, 'E2 regulates transcription and maintains the episome. When HPV integrates into the host DNA, the E2 gene is often broken, leading to unregulated overexpression of E6 and E7.'),
    (v_topic_id, '80. The L1 protein of HPV is significant because?', '["It is the primary oncogene", "It is the major capsid protein used to formulate the HPV vaccine", "It degrades p53", "It causes cell lysis"]', 1, 'The HPV vaccine consists of virus-like particles (VLPs) made entirely of the L1 capsid protein. It contains no viral DNA and cannot cause infection.');

    RAISE NOTICE 'SUCCESS: Reproductive Pathology MCQs P1 (1-80) registered.';
END $$;

COMMIT;
